# -*- coding: utf-8 -*-
# 第 10 批（A1）：空氣污染防制法（107/8/1）第1條～第50條
AP = "ENV-01"
Q = [
(AP,"第1條",1,"空污法-立法目的",
 "空氣污染防制法所揭示之立法目的為何？",
 ["為防制空氣污染，維護生活環境及國民健康，以提高生活品質","為防治水體污染，維護河川水質及水域生態，以確保用水安全","為推動溫室氣體減量，因應氣候變遷衝擊，以達成淨零排放","為管理噪音振動，維護居住安寧及國民健康，以提升環境品質"],"a",
 "第1條：為防制空氣污染，維護生活環境及國民健康，以提高生活品質，特制定本法。第2條定明主管機關在中央為行政院環境保護署。第99條授權中央主管機關訂定施行細則，第100條規定本法自公布日施行。",
 "What is the stated legislative purpose of the Air Pollution Control Act?",
 ["To prevent air pollution, maintain the living environment and public health, and improve quality of life","To control water pollution, maintain river quality and aquatic ecology, and secure safe water supply","To promote greenhouse gas reduction, respond to climate change impacts, and reach net zero emissions","To manage noise and vibration, maintain residential quiet and public health, and improve environment"],
 "Article 1 states the purpose; Article 2 designates the competent authorities."),

(AP,"第2條",1,"空污法-主管機關",
 "本法所稱主管機關，在中央、直轄市及縣（市）分別為何？",
 ["中央為行政院環境保護署；直轄市為直轄市政府；縣（市）為縣（市）政府","中央為經濟部工業局；直轄市為直轄市環保局；縣（市）為縣（市）環保局","中央為內政部營建署；直轄市為直轄市工務局；縣（市）為縣（市）建設局","中央為衛生福利部國健署；直轄市為直轄市衛生局；縣（市）為縣（市）衛生局"],"a",
 "第2條：本法所稱主管機關，在中央為行政院環境保護署；在直轄市為直轄市政府；在縣（市）為縣（市）政府。第83條並定明處罰機關：在中央由行政院環境保護署為之，在直轄市、縣（市）由該管政府為之。",
 "Who are the competent authorities at central, municipal and county levels?",
 ["Central: EPA under the Executive Yuan; municipal: municipal government; county: county government","Central: Industrial Development Bureau of MOEA; municipal: municipal EPB; county: county EPB office","Central: Construction Agency of MOI; municipal: municipal works bureau; county: county works bureau","Central: Health Promotion Administration; municipal: municipal health bureau; county: health bureau"],
 "Article 2; Article 83 mirrors this split for penalties."),

(AP,"第3條",2,"空污法-定義",
 "本法所稱污染源分為哪兩類？移動污染源之定義為何？",
 ["分為移動污染源與固定污染源；移動污染源指因本身動力而改變位置之污染源","分為點污染源與面污染源；移動污染源指以外力拖曳而改變位置之污染源","分為工業污染源與民生污染源；移動污染源指設於車輛上之各種燃燒設備","分為許可污染源與免許可污染源；移動污染源指行駛於道路上之各式車輛"],"a",
 "第3條第2款：污染源指排放空氣污染物之物理或化學操作單元，分為移動污染源（因本身動力而改變位置者）及固定污染源（移動污染源以外者）。同條第3款定義汽車為在道路上不依軌道或電力架設，而以原動機行駛之車輛，包括機車。施行細則第23條並列舉交通工具種類。",
 "Into which two categories are pollution sources divided, and how is a mobile source defined?",
 ["Mobile and stationary sources; a mobile source changes position by its own motive power","Point and area sources; a mobile source changes position by being towed by external force","Industrial and household sources; a mobile source means combustion equipment on vehicles","Permitted and exempt sources; a mobile source means any vehicle travelling on public roads"],
 "Article 3, subparagraph 2."),

(AP,"第3條",3,"空污法-控制技術",
 "本法所稱最佳可行控制技術與最低可達成排放率控制技術，其定義有何差別？",
 ["前者考量能源、環境、經濟衝擊後應採之已商業化最大減量技術；後者另考量健康衝擊並依科學方法減至最低排放率","前者考量健康衝擊後應採之尚在試驗階段技術；後者僅考量經濟成本後應採之已商業化最大減量技術","前者指成本最低且尚未商業化之技術；後者指考量能源與環境衝擊後應採之最大減量技術","前者指主管機關逐案指定之技術；後者指業者自行選定並報備之減量技術，兩者均不考量經濟衝擊"],"a",
 "第3條第11款：最佳可行控制技術指考量能源、環境、經濟之衝擊後，污染源應採取之已商業化並可行污染排放最大減量技術；最低可達成排放率控制技術指考量能源、環境、經濟、健康等衝擊後，並依據科學方法，減少污染物排放至最低排放率之技術。第6條第3項規定三級防制區新設或變更達一定規模者採最佳可行控制技術，特定大型污染源採最低可達成排放率控制技術。",
 "How do BACT and LAER differ under the Act?",
 ["BACT weighs energy, environmental and economic impacts and is commercialized maximum reduction; LAER also weighs health and uses scientific method to reach the lowest emission rate","BACT weighs health impacts and is still experimental; LAER weighs only economic cost and is a commercialized maximum reduction technique used for all new sources","BACT means the cheapest technique not yet commercialized anywhere; LAER means the maximum reduction technique after weighing only the energy and environmental impacts of a stationary source","BACT means a technique designated case by case by the authority; LAER means one chosen by the operator, and neither of them considers any economic impact at all"],
 "Article 3, subparagraph 11."),

(AP,"第3條",2,"空污法-定義",
 "本法對「怠速」及「空氣品質維護區」如何定義？",
 ["怠速指汽車停車時維持引擎持續運轉之情形；空氣品質維護區指為維護空氣品質，得限制或禁止移動污染源使用之特定區域","怠速指汽車行駛中引擎低轉速運轉之情形；空氣品質維護區指依土地利用需求劃定之各級空氣污染防制區域","怠速指引擎熄火後維持電力供應之情形；空氣品質維護區指為總量管制需求按地形氣象條件劃定之區域","怠速指汽車起步前之暖車行為；空氣品質維護區指特殊性工業區四周應規劃設置之緩衝地帶區域"],"a",
 "第3條第12款、第13款：怠速指汽車停車時，維持引擎持續運轉之情形；空氣品質維護區指為維護空氣品質，得限制或禁止移動污染源使用之特定區域。第38條規定怠速停車時間應符合中央主管機關規定，第40條規定各級主管機關得劃設空氣品質維護區實施移動污染源管制。",
 "How does the Act define idling and an air quality maintenance area?",
 ["Idling: keeping the engine running while the vehicle is parked; maintenance area: a specific area where mobile source use may be limited or banned","Idling: running the engine at low speed while driving; maintenance area: the graded air pollution control districts drawn by land use demand","Idling: keeping power on after the engine is switched off; maintenance area: an area delimited by terrain and meteorology for total quantity control","Idling: warming up the vehicle before departure; maintenance area: the buffer zone that a special industrial park developer must set aside"],
 "Article 3, subparagraphs 12 and 13; see also Articles 38 and 40."),

(AP,"第4條",1,"空污法-委託",
 "關於空氣污染訓練及防制有關事宜之辦理，本法有何規定？",
 ["各級主管機關得指定或委託（任）專責機關（構）辦理空氣污染訓練及防制有關事宜","僅中央主管機關得委託財團法人辦理空氣污染訓練，防制事宜不得委託任何機關辦理","各級主管機關應自行辦理空氣污染訓練及防制事宜，不得指定或委託其他機關（構）","各目的事業主管機關應設置專責機構辦理空氣污染訓練，並由中央主管機關核定經費"],"a",
 "第4條：各級主管機關得指定或委託（任）專責機關（構），辦理空氣污染訓練及防制之有關事宜。第50條另定各種污染源之改善由各目的事業主管機關輔導，輔導成果應每年公開於中央主管機關指定之網站。",
 "What does the Act provide about air pollution training and control affairs?",
 ["Each competent authority may designate or commission a dedicated agency to handle training and control affairs","Only the central authority may commission a foundation to handle training; control affairs may not be commissioned","Each competent authority must handle training and control itself and may not designate or commission others","Each industry authority shall establish a dedicated body for training, with its budget approved centrally"],
 "Article 4."),

(AP,"第5條",2,"空污法-防制區",
 "空氣污染防制區分為幾級？其分級標準及空氣品質標準之檢討頻率為何？",
 ["分三級：一級為國家公園及自然保護（育）區；二級為符合空品標準區；三級為未符合區；空品標準至少每四年檢討一次","分三級：一級為工業區；二級為住宅區；三級為農業區及其他區域；空氣品質標準至少每二年檢討修正一次","分二級：一級為符合空品標準區；二級為未符合區；空氣品質標準至少每五年檢討修正一次","分四級：依污染程度由輕至重排列；空氣品質標準由直轄市主管機關每三年檢討修正一次"],"a",
 "第5條：中央主管機關應視土地用途對空氣品質之需求或空氣品質狀況劃定各級防制區並公告；分為一級（國家公園及自然保護育區等依法劃定之區域）、二級（一級外符合空氣品質標準之區域）、三級（一級外未符合空氣品質標準之區域）；空氣品質標準由中央主管機關會商有關機關定之，並應至少每四年檢討一次。",
 "How many classes of air pollution control districts are there, and how often is the air quality standard reviewed?",
 ["Three classes: Class 1 national parks and nature reserves; Class 2 attainment areas; Class 3 non-attainment; standard reviewed at least every four years","Three classes: Class 1 industrial areas; Class 2 residential areas; Class 3 farming areas; the air quality standard is reviewed at least every two years","Two classes: Class 1 attainment areas and Class 2 non-attainment areas; the air quality standard must be reviewed and revised at least every five years","Four classes ranked from light to heavy pollution; the air quality standard is reviewed every three years by the municipal competent authority"],
 "Article 5."),

(AP,"第6條",3,"空污法-防制區管制",
 "一級防制區與三級防制區對新設或變更固定污染源之管制有何不同？",
 ["一級防制區除民生設施、國家公園經營管理必要設施或國防設施外不得新設或變更；三級防制區達一定規模者應採最佳可行控制技術","一級防制區僅禁止工商廠場新設；三級防制區之新設污染源一律禁止，既存污染源則免除削減義務","一級防制區得自由新設但須模式模擬；三級防制區僅需符合排放標準即可新設或變更固定污染源","一級防制區內新設須經模式模擬證明；三級防制區內既存污染源得免削減，新設者採最低可達成排放率技術"],"a",
 "第6條：一級防制區內，除維繫區內住戶民生需要之設施、國家公園經營管理必要設施或國防設施外，不得新設或變更固定污染源；三級防制區內既存固定污染源應削減排放量，新設或變更達一定規模者應採最佳可行控制技術，屬特定大型污染源者應採最低可達成排放率控制技術，並經模式模擬證明不超過容許增量限值。違反第6條第1項者依第60條處罰。",
 "How does control of new or modified stationary sources differ between Class 1 and Class 3 districts?",
 ["Class 1 bars new or modified sources except livelihood, park management or defense facilities; Class 3 requires BACT once a certain scale is reached","Class 1 bars only industrial plants from being built; in Class 3 all new sources are banned and existing sources are exempt from any reduction duty","Class 1 allows new sources freely subject to modeling; in Class 3 meeting the emission standard alone is enough to build or modify a stationary source","Class 1 requires only modeling proof for new sources; in Class 3 existing sources need no reduction and new sources must adopt LAER technology"],
 "Article 6."),

(AP,"第7條",2,"空污法-防制計畫",
 "空氣污染防制方案與地方空氣污染防制計畫之訂定與檢討期程為何？",
 ["中央應訂定防制方案並每四年檢討修正；地方應擬訂防制計畫報中央核定後公告，並每四年檢討修正","中央應訂定防制方案並每二年檢討修正；地方應擬訂防制計畫報行政院備查，並每二年檢討修正","中央應訂定防制方案並每五年檢討修正；地方防制計畫由地方自行公告，無須報中央核定或檢討","中央防制方案由行政院核定；地方防制計畫應每年檢討修正，並報經濟部會商中央主管機關同意"],"a",
 "第7條：中央主管機關應訂定空氣污染防制方案，並應每四年檢討修正；直轄市、縣（市）主管機關應依第6條規定及該方案擬訂空氣污染防制計畫，報中央主管機關核定後公告之，並應每四年檢討修正；擬訂時應考量空氣污染物流通性質，會商鄰近地方主管機關。施行細則第7條、第8條規定方案及計畫應載明之內容。",
 "What are the timelines for the national air pollution control program and local control plans?",
 ["The central authority sets a program reviewed every four years; local plans are approved centrally, announced, and reviewed every four years","The central authority sets a program reviewed every two years; local plans are filed with the Executive Yuan and reviewed every two years","The central authority sets a program reviewed every five years; local plans are announced locally with no central approval or review","The program is approved by the Executive Yuan; local plans are reviewed yearly with consent of the Ministry of Economic Affairs"],
 "Article 7; contents are detailed in Enforcement Rules Articles 7 and 8."),

(AP,"第8條",3,"空污法-總量管制",
 "未符合空氣品質標準之總量管制區內，既存及新設固定污染源分別有何義務？",
 ["既存者應申請認可排放量並依指定目標與期限削減；新設或變更達一定規模者應採最佳可行控制技術並取得足供抵換之排放量","既存者免申請認可但應每年申報排放量；新設或變更者僅需模式模擬證明不超過容許增量限值即可設置","既存者應停止操作至符合空氣品質標準為止；新設或變更者一律禁止，且不得以排放量抵換方式設置","既存者由中央主管機關逕行核定削減量；新設或變更者僅需採用最低可達成排放率控制技術，免取得抵換量"],"a",
 "第8條：未符合空氣品質標準之總量管制區，既存固定污染源應向直轄市、縣（市）主管機關申請認可其污染物排放量，並依中央主管機關指定之目標與期限削減；新設或變更達一定規模者應採最佳可行控制技術，屬特定大型污染源者採最低可達成排放率控制技術，且應取得足供抵換污染物增量之排放量。實際削減量差額經認可後得保留、抵換或交易。",
 "In a non-attainment total quantity control zone, what must existing and new stationary sources do?",
 ["Existing sources must have emissions approved and reduce them by the set target and deadline; new ones must adopt BACT and obtain offsets for the increment","Existing sources need no approval but report emissions yearly; new or modified sources need only modeling proof of staying within the allowable increment limit","Existing sources must halt operation until the air quality standard is met; new or modified sources are banned outright and cannot be built using emission offsets","Existing sources have reductions set directly by the central authority; new or modified sources need only adopt LAER technology and need not obtain any offsets"],
 "Article 8, paragraphs 3 and 4."),

(AP,"第9條",2,"空污法-抵換來源",
 "固定污染源供抵換污染物增量之排放量，應自何種來源取得？",
 ["固定污染源保留之實際削減量差額、交易或拍賣取得之排放量、改善移動污染源所減少之排放量及其他經中央認可者","僅得自同一公私場所其他污染源之削減量取得，且不得以交易、拍賣或改善移動污染源方式取得排放量","僅得向中央主管機關價購排放量，或由目的事業主管機關按產業別逐年配發，不得於市場交易取得","得自營建工程繳納之空氣污染防制費折抵，或由地方主管機關依其空氣品質改善成果無償配發取得"],"a",
 "第9條：抵換之排放量應自下列來源取得，並以較低之比例抵換：一、固定污染源依規定保留之實際削減量差額。二、交易或拍賣取得之排放量。三、改善移動污染源所減少之排放量。四、其他經中央主管機關認可之排放量。拍賣由各級主管機關辦理者，其拍賣辦法由中央主管機關定之。第87條並定明拍賣所得應納入空氣污染防制基金。",
 "From what sources may offsets for emission increases be obtained?",
 ["Retained actual reduction differentials, emissions bought or auctioned, reductions from improving mobile sources, and others recognized centrally","Only from other sources at the same premises; trading, auction and mobile source improvement may not be used to obtain offset emissions","Only by purchasing emissions from the central authority or by yearly allocation from industry authorities, with no market trading permitted","By deducting construction air pollution fees already paid, or by free allocation from local authorities based on air quality improvement results"],
 "Article 9, paragraph 1."),

(AP,"第10條",2,"空污法-總量管制計畫",
 "未符合空氣品質標準之總量管制區，其總量管制計畫應包括哪些事項？",
 ["污染物種類、減量目標與期程、各地方須執行之削減量與期程、污染物抵換比例、新設或變更污染源審核原則及運作方式","污染物容許增量限值、避免空氣品質惡化措施、新設或變更固定污染源審核原則、運作方式及其他事項","監測站設置地點、空氣品質惡化警告發布方式、緊急防制措施內容、交通工具管制措施及運作方式","空氣污染防制費費率、基金支用項目、獎勵與補助對象、檢舉獎金比例及新設污染源審核原則"],"a",
 "第10條第2項：未符合空氣品質標準之總量管制區，其總量管制計畫應包括污染物種類、減量目標、減量期程、區內各地方主管機關須執行污染物削減量與期程、第9條第1項污染物抵換之比例、新設或變更固定污染源審核原則、運作方式及其他事項。第1項則規定符合空氣品質標準之總量管制區應包括容許增量限值及避免空氣品質惡化措施等。",
 "What must a total quantity control plan cover in a non-attainment zone?",
 ["Pollutant types, reduction targets and schedule, each local authority's reduction duty, offset ratios, review principles for new sources and operating methods","Allowable increment limits, measures to prevent air quality deterioration, review principles for new or modified stationary sources, and other matters","Monitoring station siting, deterioration warning procedures, emergency control measures, transport restriction measures, and operating methods","Air pollution control fee rates, fund spending items, subsidy recipients, whistleblower reward ratios and review principles for new sources"],
 "Article 10, paragraph 2 (paragraph 1 covers attainment zones)."),

(AP,"第11條",2,"空污法-地方計畫",
 "總量管制區內之地方主管機關，依總量管制計畫應如何辦理？",
 ["應據以訂定及修正空氣污染防制計畫；於未符合空品標準區並應指定削減之固定污染源、削減量及期程","應據以訂定排放標準並公告實施，且得逕行命區內所有固定污染源停工至符合空氣品質標準為止","應報請中央主管機關代為指定削減對象，地方不得自行指定固定污染源之削減量及削減期程","應每年編列預算補助區內固定污染源改善，並免除既存固定污染源之排放量削減與申報義務"],"a",
 "第11條：總量管制區內之直轄市、縣（市）主管機關，應依第10條總量管制計畫訂定及修正空氣污染防制計畫；於未符合空氣品質標準之總量管制區者，應依總量管制計畫所定須執行污染物削減量與期程之規定，指定削減污染物排放量之固定污染源、削減量及期程。施行細則第8條規定該計畫應載明指定削減之固定污染源。",
 "What must local authorities in a total quantity control zone do under the plan?",
 ["Set and revise their air pollution control plan, and in non-attainment zones designate the sources, reduction amounts and schedules","Set and announce emission standards, and may directly order every source in the zone to shut down until the standard is attained","Ask the central authority to designate the reduction targets, since local authorities may not designate sources or amounts themselves","Budget subsidies each year for source improvement, and exempt existing stationary sources from reduction and reporting duties"],
 "Article 11."),

(AP,"第12條",2,"空污法-實施程序",
 "第八條至第十一條關於總量管制之規定，應於何時、依何程序實施？",
 ["應於建立污染源排放量查核系統及排放交易制度後，由中央主管機關會商經濟部報請行政院分期分區核定公告實施","應於本法公布後一年內，由中央主管機關逕行公告全國同步實施，無須會商其他機關或報請行政院核定","應於地方主管機關完成空氣品質監測站設置後，由各直轄市、縣（市）主管機關自行公告分區實施","應於中央主管機關訂定排放標準後，由經濟部會商中央主管機關報請立法院同意後分期分區實施"],"a",
 "第12條：第8條至第11條關於總量管制之規定，應於建立污染源排放量查核系統及排放交易制度後，由中央主管機關會商經濟部報請行政院分期分區核定公告實施之。第8條第1項並定明中央主管機關得依地形、氣象條件指定總量管制區並訂定總量管制計畫。",
 "When and by what procedure do the total quantity control provisions take effect?",
 ["After an emissions audit system and trading system are built, the central authority with MOEA reports to the Executive Yuan for phased approval","Within one year of promulgation the central authority announces nationwide implementation directly, without consulting or reporting to anyone","After local authorities finish building monitoring stations, each municipality or county announces implementation in its own area","After emission standards are set, MOEA with the central authority seeks Legislative Yuan consent for phased implementation"],
 "Article 12."),

(AP,"第13條",2,"空污法-監測站",
 "關於空氣品質監測站之設置，本法有何規定？",
 ["中央主管機關應於石化工業區所在之鄉鎮市區、各級主管機關應選定適當地點設站，並定期公布空氣品質狀況及原始資料","僅中央主管機關得於石化工業區設置空氣品質監測站，地方主管機關不得設站，且監測資料每五年公布一次","監測站應由石化工業區開發者自行設置及維護，各級主管機關僅負責查核，監測資料一律不對外公布","監測站設置地點由行政院核定，各級主管機關僅得公布空氣品質指標，不得公布原始監測資料"],"a",
 "第13條：中央主管機關應於石化工業區所在之鄉鎮市區、各級主管機關應選定適當地點，設置空氣品質監測站，定期公布空氣品質狀況及其原始資料；監測站設置及監測之準則，由中央主管機關定之。第15條另規定特殊性工業區開發者應設置空氣品質監測設施。",
 "What does the Act require regarding air quality monitoring stations?",
 ["The central authority must site stations in townships hosting petrochemical parks, all authorities pick suitable sites and publish data and raw records","Only the central authority may set up stations; local authorities may not, and monitoring data is published once every five years","Stations must be built and maintained by petrochemical park developers, with authorities only auditing and no data released to the public","Station sites are approved by the Executive Yuan and the authorities may publish only the air quality index and never the raw monitoring records"],
 "Article 13."),

(AP,"第14條",2,"空污法-緊急防制",
 "空氣品質有嚴重惡化之虞時，各級主管機關及公私場所應如何處理？",
 ["各級主管機關及公私場所應即採取緊急防制措施；主管機關應發布惡化警告，並得禁止或限制交通工具使用及公私場所排放","公私場所應自行停工並報備，各級主管機關僅得發布空氣品質預報，不得禁止或限制交通工具之使用及排放","應由中央主管機關報請行政院宣布進入緊急狀態後，地方主管機關始得採取任何緊急防制措施","僅得對工商廠場實施排放限制，對機關、學校之活動及交通工具之使用均不得禁止或加以限制"],"a",
 "第14條第1項：因氣象變異或其他原因，致空氣品質有嚴重惡化之虞時，各級主管機關及公私場所應即採取緊急防制措施；各級主管機關應發布空氣品質惡化警告，並得禁止或限制交通工具之使用、公私場所空氣污染物之排放及機關、學校之活動。違反者依第65條處罰，公私場所處新臺幣二萬元以上一百萬元以下罰鍰，工商廠場處十萬元以上二千萬元以下。",
 "What must authorities and premises do when air quality may deteriorate severely?",
 ["All authorities and premises must take emergency measures at once; authorities issue warnings and may restrict vehicles and emissions from premises","Premises shut down on their own initiative and report it; authorities may only issue forecasts and may not restrict the use of vehicles","Only after the Executive Yuan declares a state of emergency at the central authority's request may local authorities take any emergency measures","Only industrial plants may face emission limits; activities of agencies and schools and the use of vehicles may never be banned or restricted"],
 "Article 14, paragraph 1; penalties in Article 65."),

(AP,"第14條",3,"空污法-電業增量",
 "電業為執行緊急防制措施或配合降低燃煤發電而增加燃氣發電之排放量，其核可條件與施行期限為何？",
 ["增量須報中央目的事業主管機關審核並送中央主管機關核可，且應低於所減少之排放量；該規定施行至一百十四年十二月三十一日止","增量僅須報請經濟部備查即可，且無須低於所減少之排放量；該規定施行至一百二十年十二月三十一日止為限","增量應報請行政院環境保護署核可，並得超過所減少之排放量；該規定並無施行期限之限制規定","增量由電業自行認定並公開於網站，不受許可證年許可燃料用量限制；該規定施行至一百十年底止"],"a",
 "第14條第2項、第3項、第5項：電業為執行緊急防制措施或配合降低燃煤發電而調整發電燃料種類，致增加燃氣發電之燃料用量及排放量者，其增量得報經中央目的事業主管機關審核，並送中央主管機關核可後，不受第24條第4項所定辦法核發許可證登載之年許可燃料用量及排放量限制；調整增加之排放量應低於所減少之排放量；一百零七年六月二十五日修正之第2項及第3項規定，施行至一百十四年十二月三十一日止。",
 "What conditions and sunset apply to a power utility's extra gas-fired emissions?",
 ["The increase needs industry authority review plus central approval and must be less than the reduction achieved; the rule runs to 31 December 2025","The increase need only be filed with MOEA and it need not be lower than the reduction achieved; the rule instead runs until 31 December 2031","The increase requires EPA approval and may exceed the reduction achieved; no sunset date applies to this provision at all","The utility may determine the increase itself and post it online free of permit fuel limits; the rule ran only to the end of 2021"],
 "Article 14, paragraphs 2, 3 and 5."),

(AP,"第15條",2,"空污法-特殊性工業區",
 "特殊性工業區開發者依本法應辦理哪些事項？",
 ["應於區界內之四周規劃設置緩衝地帶，並於適當地區設置空氣品質監測設施，其記錄及申報依中央所定標準辦理","應於區外設置隔離綠帶並代為徵收空氣污染防制費，監測設施則由地方主管機關設置及維護管理","應設置固定污染源自動監測設施並與中央主管機關連線，緩衝地帶及監測設施均由目的事業主管機關設置","應設置緩衝地帶並自行訂定較嚴之排放標準，報中央主管機關備查後實施，免設空氣品質監測設施"],"a",
 "第15條：特殊性工業區開發者，應於區界內之四周規劃設置緩衝地帶及適當地區設置空氣品質監測設施；其類別、緩衝地帶、空氣品質監測狀況記錄、申報、監測設施設置規範、記錄及申報之標準由中央主管機關定之，中央主管機關並應定期公布申報狀況及原始資料。違反者依第58條處新臺幣五十萬元以上二千萬元以下罰鍰。施行細則第10條並定明開發之意義。",
 "What must the developer of a special industrial park do?",
 ["Plan a buffer zone along the park boundary and install air quality monitoring facilities at suitable spots, recording and reporting per central standards","Plant an isolation green belt outside the park and collect air pollution fees, while local authorities install and maintain the monitoring facilities","Install continuous monitoring linked to the central authority, with the buffer zone and monitors provided by the relevant industry authority","Provide a buffer zone and set its own stricter emission standards for filing with the central authority, with no monitoring facilities required"],
 "Article 15; penalties in Article 58."),

(AP,"第16條",2,"空污法-空污費",
 "空氣污染防制費之徵收對象，就固定污染源與營建工程分別為何？",
 ["固定污染源向所有人徵收，所有人非使用人或管理人者向實際使用人或管理人徵收；營建工程向營建業主徵收","固定污染源一律向使用人徵收，不得向所有人徵收；營建工程則向承攬施工之營造廠商徵收其費額","固定污染源向目的事業主管機關徵收後轉嫁；營建工程向建築物起造人之委任建築師徵收其費額","固定污染源向燃料銷售者或進口者徵收；營建工程向工地所在地之土地所有權人徵收其應繳費額"],"a",
 "第16條第1項第1款：固定污染源依其排放空氣污染物之種類及數量，向污染源之所有人徵收，其所有人非使用人或管理人者，向實際使用人或管理人徵收；其為營建工程者，向營建業主徵收；經中央主管機關指定公告之物質，得依銷售數量向銷售者或進口者徵收。施行細則第11條定明營建業主之意義。第2款則規定移動污染源之徵收方式。",
 "Who pays the air pollution control fee for stationary sources and for construction projects?",
 ["Stationary sources: the owner, or the actual user or manager if the owner is neither; construction projects: the construction owner","Stationary sources: always the user and never the owner; construction projects: the contractor that actually carries out the works","Stationary sources: the industry authority, which passes the cost on; construction projects: the architect commissioned by the builder","Stationary sources: the fuel seller or importer; construction projects: the owner of the land on which the site is located"],
 "Article 16, paragraph 1, subparagraph 1; see Enforcement Rules Article 11."),

(AP,"第17條",3,"空污法-空污費撥交",
 "空氣污染防制費之徵收機關及撥交比率為何？地方得建議之費率調整幅度為何？",
 ["營建工程由地方徵收，其餘由中央徵收；固定污染源款項撥交百分之六十、移動污染源撥交百分之二十；得於費率增減百分之三十範圍內建議","營建工程由中央徵收，其餘由地方徵收；固定污染源撥交百分之二十、移動污染源撥交百分之六十；得於費率增減百分之十範圍內建議","全部由中央徵收；固定污染源撥交百分之五十、移動污染源撥交百分之五十；地方不得提出收費費率之調整建議","全部由地方徵收後解繳中央；固定污染源撥交百分之八十、移動污染源撥交百分之四十；得於費率增減百分之五十範圍內建議"],"a",
 "第17條：空氣污染防制費除營建工程由直轄市、縣（市）主管機關徵收外，由中央主管機關徵收；中央由固定污染源所收款項應以百分之六十撥交該污染源所在地方主管機關，由移動污染源所收款項應以百分之二十撥交使用者設籍地或油燃料銷售地之地方主管機關；費率施行滿一年後，總量管制區內地方主管機關得依前項費率增減百分之三十範圍內提出建議收費費率，由中央核定公告。",
 "Who collects the fee, what shares are transferred, and how far may local authorities propose adjusting rates?",
 ["Local authorities collect for construction, the centre for the rest; 60% of stationary and 20% of mobile revenue is transferred; ±30% rate proposals allowed","The centre collects for construction and localities the rest; 20% of stationary and 60% of mobile revenue is transferred; ±10% rate proposals allowed","All is collected centrally; 50% of stationary and 50% of mobile revenue is transferred; local authorities may not propose any rate adjustment at all","All is collected locally and remitted centrally; 80% of stationary and 40% of mobile revenue transferred; ±50% rate proposals are allowed"],
 "Article 17."),

(AP,"第18條",3,"空污法-基金管理會",
 "空氣污染防制費成立基金者，其基金管理會之組成有何限制？",
 ["學者、專家及環保團體代表應占管理會名額三分之二以上，不得由相關產業之大股東擔任，環保團體代表不得低於名額六分之一","學者、專家及環保團體代表應占管理會名額二分之一以上，相關產業大股東得擔任委員，環保團體代表不得低於名額三分之一","學者、專家及環保團體代表應占管理會名額四分之三以上，並由目的事業主管機關指派，環保團體代表不得低於名額五分之一","管理會委員全部由各級主管機關人員擔任，不得聘任學者專家或環保團體代表，亦不受利益迴避規定之限制"],"a",
 "第18條第2項、第3項：各級主管機關得成立基金管理運用並成立基金管理會監督運作，其中學者、專家及環保團體代表等，應占管理會名額三分之二以上，並不得由相關產業之大股東擔任，且環保團體代表不得低於管理會名額六分之一；代表就審議案件之利益迴避，準用行政程序法第32條及第33條規定。施行細則第13條定明大股東指持股或資本額百分之五以上者。",
 "What limits apply to the composition of the fee fund's management committee?",
 ["Scholars, experts and NGO representatives must hold at least two thirds of seats, exclude major shareholders of the industry, and NGOs at least one sixth","Scholars, experts and NGO representatives must hold at least one half of seats, major shareholders may serve, and NGO representatives at least one third","Scholars, experts and NGO representatives must hold at least three quarters of seats, appointed by industry authorities, and NGOs at least one fifth","All committee members are officials of the competent authorities; no scholars or NGO representatives may serve and recusal rules do not apply"],
 "Article 18, paragraphs 2 and 3; Enforcement Rules Article 13."),

(AP,"第19條",2,"空污法-減免獎勵",
 "公私場所固定污染源採行防制減量措施有效減量者，得向何機關申請何種優惠？",
 ["得向直轄市、縣（市）主管機關申請獎勵；已繳納空氣污染防制費者，得申請減免空氣污染防制費","得向中央主管機關申請補助設備經費；已繳納空氣污染防制費者，得申請全額退還已繳納之費額","得向目的事業主管機關申請租稅減免；已繳納空氣污染防制費者，得申請延長繳費期限三年","得向直轄市、縣（市）主管機關申請免除排放標準之適用；並得申請免除定期申報排放量義務"],"a",
 "第19條：公私場所固定污染源因採行污染防制減量措施，能有效減少污染排放量達一定程度者，得向直轄市、縣（市）主管機關申請獎勵；其已依第16條第1項繳納空氣污染防制費者，得向直轄市、縣（市）主管機關申請減免空氣污染防制費；減免與獎勵之對象、申請資格、審查程序等辦法由中央主管機關會商有關機關定之。",
 "Where and for what may a source that effectively cuts emissions apply?",
 ["To the municipal or county authority for an incentive; if the fee has been paid, for a reduction or waiver of the air pollution control fee","To the central authority for an equipment subsidy; if the fee has been paid, for a full refund of all fees already remitted","To the relevant industry authority for tax relief; if the fee has been paid, for a three-year extension of the payment deadline","To the municipal or county authority for exemption from emission standards, and also from the duty to report emissions periodically"],
 "Article 19."),

(AP,"第20條",2,"空污法-排放標準",
 "有關固定污染源排放標準之訂定，本法有何規定？",
 ["排放標準由中央依業別、設施、污染物項目或區域訂定；地方得擬訂個別較嚴標準報中央核定；有害空氣污染物標準值依健康風險評估結果訂定","排放標準一律由直轄市、縣（市）主管機關訂定並公告實施；中央主管機關僅得公告有害空氣污染物之種類，不得訂定排放標準值","排放標準由目的事業主管機關按產業別訂定；地方不得擬訂較嚴標準，有害空氣污染物則不納入排放標準規範","排放標準由公私場所自行提報並經技師簽證後實施；中央主管機關僅就有害空氣污染物公告健康風險評估方式"],"a",
 "第20條：公私場所固定污染源排放空氣污染物，應符合排放標準；排放標準由中央主管機關依特定業別、設施、污染物項目或區域會商有關機關定之，地方主管機關得因特殊需要擬訂個別較嚴之排放標準，報請中央會商核定；排放標準應含有害空氣污染物，其標準值應依健康風險評估結果及防制技術可行性訂定，種類及評估作業方式由中央公告。違反第1項依第62條第1項第1款處罰。",
 "What does the Act provide on setting stationary source emission standards?",
 ["The centre sets standards by industry, facility, pollutant or area; localities may propose stricter ones for approval; hazardous limits follow risk assessment","Local authorities alone set and announce all emission standards; the centre may list hazardous pollutants only and may not set any limit values for them at all","Industry authorities set standards by sector; localities may not propose stricter ones and hazardous air pollutants are left out of the standards","Premises propose their own standards certified by an engineer; the centre only announces the risk assessment method for hazardous pollutants"],
 "Article 20; violations penalized under Article 62(1)(1)."),

(AP,"第21條",2,"空污法-排放量申報",
 "具中央指定公告固定污染源之公私場所，其排放量申報頻率與期限為何？",
 ["應按季於每年一月、四月、七月及十月底前，向直轄市、縣（市）主管機關申報前一季空氣污染物排放量","應按月於每月十五日前，向中央主管機關申報前一個月之空氣污染物排放量及燃料使用量紀錄","應按年於每年三月底前，向目的事業主管機關申報前一年度空氣污染物排放量及防制設施運轉紀錄","應按半年於每年六月及十二月底前，向直轄市、縣（市）主管機關申報前半年空氣污染物排放量"],"a",
 "第21條：公私場所具有經中央主管機關指定公告之固定污染源者，應按季於每年一月、四月、七月及十月底前，向直轄市、縣（市）主管機關申報其固定污染源前一季空氣污染物排放量；計算、記錄、申報內容、程序與方式、查核等辦法由中央主管機關定之。違反者依第62條第1項第2款處罰。",
 "How often and by when must designated stationary sources report emissions?",
 ["Quarterly, by the end of January, April, July and October, to the municipal or county competent authority for the previous quarter","Monthly, by the fifteenth of each month, to the central competent authority for the previous month's emissions and fuel use records","Annually, by the end of March, to the relevant industry authority for the previous year's emissions and control equipment records","Semi-annually, by the end of June and December, to the municipal or county authority for the preceding half year's emissions"],
 "Article 21; penalties under Article 62(1)(2)."),

(AP,"第22條",2,"空污法-自動監測",
 "經中央指定公告之固定污染源，其自動監測設施有何義務？",
 ["應於規定期限內完成設置並連續監測，向地方主管機關申請認可；經指定公告應連線者並應連線及公開於地方主管機關網站","應於取得操作許可證後自行設置，無須申請認可，監測結果僅需留存備查，不必向主管機關申報或連線","應由地方主管機關設置並維護，公私場所僅需提供場地及電力，監測結果由主管機關逕行公開於網站","應委託環境檢驗測定機構每季檢測一次即可，免設自動監測設施，亦免與主管機關連線或公開資訊"],"a",
 "第22條：公私場所具有經中央主管機關指定公告之固定污染源者，應於規定期限內完成設置自動監測設施，連續監測其操作或空氣污染物排放狀況，並向直轄市、縣（市）主管機關申請認可；經指定公告應連線者，應於規定期限內完成連線並公開於地方主管機關網站；其餘污染源必要時得指定公告應定期檢驗測定。監測或檢驗測定結果應作成紀錄並申報。違反者依第62條第1項第3款處罰。",
 "What duties apply to automatic monitoring facilities at designated sources?",
 ["Install within the set period, monitor continuously, apply to the local authority for approval, and if designated, link up and publish on its website","Install after obtaining an operating permit with no approval needed, keeping results on file only, with no reporting, linkage or publication at all","The local authority installs and maintains them while the premises supply space and power, and the authority publishes the results on its website","Commissioning a licensed testing organization once a quarter suffices, with no automatic monitors, no data linkage and no public disclosure"],
 "Article 22; penalties under Article 62(1)(3)."),

(AP,"第23條",2,"空污法-收集與操作量",
 "公私場所對空氣污染物之收集及固定污染源操作量，本法有何要求？",
 ["應有效收集各種空氣污染物並維持防制或監測設施正常運作；固定污染源最大操作量不得超過防制設施之最大處理容量","應有效收集空氣污染物但防制設施得於歲修期間停止運作；固定污染源最大操作量不得低於防制設施處理容量","僅須維持監測設施正常運作即可，防制設施得視空氣品質狀況間歇運轉；操作量不受防制設施容量之限制","應由主管機關逐案核定收集效率及操作量上限；未經核定者，固定污染源之操作量得不受任何限制"],"a",
 "第23條：公私場所應有效收集各種空氣污染物，並維持其空氣污染防制設施或監測設施之正常運作；其固定污染源之最大操作量，不得超過空氣污染防制設施之最大處理容量。固定污染源及其收集、防制或監測設施之規格、設置、操作、檢查、保養、記錄等辦法由中央主管機關定之，營建工程及逸散性粒狀污染物之管理辦法即依本條第2項訂定。違反者依第62條第1項第4款處罰。",
 "What does the Act require on pollutant collection and maximum operating capacity?",
 ["Collect all pollutants effectively and keep control or monitoring facilities running; maximum operating rate may not exceed control capacity","Collect pollutants effectively though control facilities may stop during overhauls; maximum operating rate may not fall below control capacity","Only monitoring facilities need to run normally and control facilities may run intermittently; operating rate is not tied to control capacity","The authority approves collection efficiency and capacity case by case; without such approval the operating rate faces no limit whatsoever"],
 "Article 23; the construction and fugitive dust regulations are made under paragraph 2."),

(AP,"第24條",2,"空污法-許可證",
 "經中央指定公告之固定污染源，其設置與操作許可證之申請程序為何？",
 ["設置或變更前應檢具空氣污染防制計畫申請設置許可證；設置或變更後應檢具符合規定之證明文件申請操作許可證","設置前應申請操作許可證，操作滿一年後再補申請設置許可證，兩者均向中央主管機關提出申請","設置或變更前僅需報請地方主管機關備查，操作後三個月內申請操作許可證，免檢具防制計畫","設置或變更前應向目的事業主管機關申請設置許可，操作許可證則由環境工程技師逕行核發"],"a",
 "第24條：公私場所具有經中央主管機關指定公告之固定污染源，應於設置或變更前檢具空氣污染防制計畫，向直轄市、縣（市）主管機關或中央委託之機關申請及取得設置許可證，並依許可證內容設置或變更；設置或變更後應檢具符合本法規定之證明文件申請及取得操作許可證，並依許可證內容操作；核發前應將申請資料登載於公開網站供民眾查詢及表示意見。未取得許可證逕行設置或操作者依第63條處罰。",
 "What is the permit procedure for designated stationary sources?",
 ["Before installing or modifying, submit a control plan for an installation permit; afterwards submit compliance documents for an operating permit","Apply for the operating permit before installation and add the installation permit after one year of operation, both filed with the central authority","Before installing or modifying, merely file with the local authority, then apply for an operating permit within three months without a control plan","Apply to the relevant industry authority for the installation permit, while the operating permit is issued directly by an environmental engineer"],
 "Article 24; unlicensed installation or operation is penalized by Article 63."),

(AP,"第25條",2,"空污法-重新申請",
 "公私場所在哪些情形下應重新申請核發許可證？",
 ["因遷移或變更產業類別者應重新申請設置及操作許可證；因公告總量管制或排放標準修正致內容不符者應於公告期限內重新申請操作許可證","僅因遷移者須重新申請設置及操作許可證，變更產業類別者僅需報備；排放標準修正時原許可證繼續有效至期滿為止","因負責人變更或公司名稱變更者應重新申請設置及操作許可證；排放標準有修正者由主管機關逕行換發新證","因防制設施更新或增設監測設施者應重新申請操作許可證；遷移者僅需辦理許可證內容之變更登記"],"a",
 "第25條：公私場所因遷移或變更產業類別，應重新申請核發設置及操作許可證；已取得操作許可證者，因中央主管機關公告實施總量管制或據以核發操作許可證之排放標準有修正，致其操作許可證內容不符規定者，應於中央主管機關公告之期限內重新申請核發操作許可證。施行細則第18條定明變更產業類別指同次變更全部之產業類別。違反者依第62條第1項第6款處罰。",
 "In which situations must a permit be applied for anew?",
 ["On relocation or change of industry category, both permits; and when total quantity control or a revised standard makes the permit non-compliant","Only on relocation; a change of industry category needs mere notification, and a revised standard leaves the permit valid until it expires","On a change of responsible person or company name, both permits; when a standard is revised the authority reissues the permit on its own","On renewing control equipment or adding monitors, the operating permit; relocation requires only registering a change to the permit content"],
 "Article 25; Enforcement Rules Article 18."),

(AP,"第26條",2,"空污法-技師簽證",
 "第二十四條之空氣污染防制計畫及證明文件，應由何人簽證？",
 ["應經依法登記執業之環境工程技師或其他相關專業技師簽證；政府機關、公營事業或公法人得由內部取得技師證書者辦理","應經公私場所之空氣污染防制專責人員簽證即可，無須由專業技師簽證，政府機關及公營事業則免除簽證義務","應經環境檢驗測定機構之檢驗人員簽證，並由目的事業主管機關複核後送主管機關審查","應經直轄市、縣（市）主管機關指定之學者專家簽證，公營事業機構得由其負責人自行簽證"],"a",
 "第26條：第24條第1項之空氣污染防制計畫及同條第2項之證明文件，應經依法登記執業之環境工程技師或其他相關專業技師簽證；政府機關、公營事業機構或公法人於前項情形，得由其內依法取得技師證書者辦理簽證。第35條並規定技師證號資料應公開於中央主管機關指定之網站。",
 "Who must certify the control plan and compliance documents under Article 24?",
 ["A duly registered practising environmental engineer or other relevant professional engineer; public bodies may use their own certified staff","The premises' own dedicated air pollution control personnel may certify them, and government agencies are exempt from certification entirely","Testing personnel of a licensed environmental testing organization, reviewed by the industry authority before submission to the authority","Scholars designated by the municipal or county competent authority, while state enterprises may have their own head certify the documents"],
 "Article 26."),

(AP,"第27條",3,"空污法-總量與濃度",
 "同一公私場所有數排放相同空氣污染物之固定污染源者，得申請何種特別管制方式？",
 ["得申請改善其排放空氣污染物總量及濃度，經核准後個別污染源排放得不受排放標準限制，並以核准之總量及濃度限值為排放標準","得申請免除排放標準之適用一年，期滿後應回歸排放標準，且不得以核准之總量及濃度限值作為其排放標準","得申請將數污染源合併為一張操作許可證，但個別污染源排放仍應分別符合中央主管機關所定之排放標準","得申請以繳納加倍空氣污染防制費方式免除排放標準之適用，並由中央主管機關逐年核定其排放總量"],"a",
 "第27條：同一公私場所有數排放相同空氣污染物之固定污染源者，得向直轄市、縣（市）主管機關申請改善其排放空氣污染物總量及濃度，經審查核准後，個別污染源之排放得不受第20條第1項及第2項所定排放標準之限制；該公私場所應以主管機關核准之總量及濃度限值為其排放標準。違反第2項或相關辦法者依第62條第1項第7款處罰。",
 "What special control option exists where several sources emit the same pollutant?",
 ["Apply to improve total quantity and concentration; once approved, individual sources escape the standard and the approved limits become their standard","Apply for a one-year exemption from the emission standard, after which the standard applies again and approved limits cannot serve as the standard","Apply to merge several sources into one operating permit, though each source must still separately meet the centrally set emission standard","Apply to pay a doubled air pollution control fee in lieu of meeting the standard, with total emissions approved annually by the central authority"],
 "Article 27."),

(AP,"第28條",2,"空污法-燃料許可",
 "固定污染源使用含生煤或中央指定公告之燃料，應符合何種規定？",
 ["應符合中央主管機關所定燃料種類混燒比例及成分之標準，並取得直轄市、縣（市）主管機關核發之使用許可證始得為之","應符合中央主管機關所定成分標準即可，無須取得使用許可證，惟應每季向目的事業主管機關申報使用情形","應取得中央主管機關核發之製造許可，並由環境工程技師簽證後始得使用，其使用情形免作成紀錄申報","應向直轄市、縣（市）主管機關報備混燒比例，並由主管機關逐批抽驗合格後始得使用該批燃料"],"a",
 "第28條：公私場所固定污染源所使用之燃料及輔助燃料，含生煤或其他中央主管機關指定公告者，應符合中央主管機關所定燃料種類混燒比例及成分之標準，並申請及取得直轄市、縣（市）主管機關核發之使用許可證，始得為之；其使用情形應作成紀錄並依規定申報。違反者依第64條第1款處罰。",
 "What applies to fuels containing raw coal or other designated fuels?",
 ["They must meet the centrally set blending ratio and composition standards and a use permit must be obtained from the local competent authority","Meeting the composition standard suffices with no use permit needed, though usage must be reported quarterly to the industry authority","A manufacturing licence from the central authority plus engineer certification is needed, and usage records need not be kept or reported","The blending ratio is merely filed with the local authority, which samples and clears each batch before that batch may be used"],
 "Article 28; penalties under Article 64(1)."),

(AP,"第29條",2,"空污法-易致空污物質",
 "使用易致空氣污染之物質者，依本法應如何辦理？",
 ["應先檢具有關資料向直轄市、縣（市）主管機關申請許可，經審查合格核發許可證後始得為之，使用情形應作成紀錄並申報","應於使用後三十日內向中央主管機關報備，並將使用情形作成紀錄留存備查，無須事先取得任何許可","應由目的事業主管機關按產業別公告免予許可之物質清單，其餘物質使用後每年申報一次即可","應取得環境檢驗測定機構出具之合格證明並報請主管機關備查，其使用情形免作成紀錄或申報"],"a",
 "第29條：使用易致空氣污染之物質者，應先檢具有關資料，向直轄市、縣（市）主管機關申請許可，經審查合格核發許可證後始得為之；其使用情形應作成紀錄並依規定申報。易致空氣污染之物質由中央主管機關會商有關機關公告之。違反者依第64條第2款處罰，並得廢止其使用許可或勒令歇業。",
 "How must a user of substances prone to causing air pollution proceed?",
 ["Submit documents to the local authority for a permit in advance, use only after the permit is issued, and record and report actual usage","Notify the central authority within thirty days after use and keep usage records on file, with no prior permit of any kind required","Industry authorities announce an exemption list by sector, and use of other substances is reported once a year after the fact","Obtain a certificate from a licensed testing organization and file it with the authority, with no usage records or reports needed"],
 "Article 29; penalties under Article 64(2)."),

(AP,"第30條",3,"空污法-許可證展延",
 "依本法核發之許可證有效期間為何？展延應於何時提出？經核准展延之有效期間為何？",
 ["有效期間五年；期滿仍須繼續使用者應於屆滿前三至六個月內提出展延申請；經核准展延者有效期間為三年以上五年以下","有效期間三年；期滿仍須繼續使用者應於屆滿前一至三個月內提出展延申請；經核准展延者有效期間為五年以上十年以下","有效期間十年；期滿仍須繼續使用者應於屆滿前六至十二個月內提出展延申請；經核准展延者有效期間為一年以上三年以下","有效期間五年；期滿仍須繼續使用者應於屆滿後三十日內補提展延申請；經核准展延者有效期間一律為五年"],"a",
 "第30條第1項：依第24條第1項、第2項、第28條第1項及第29條第1項核發之許可證，有效期間為五年；期滿仍須繼續使用者，應於屆滿前三至六個月內向直轄市、縣（市）主管機關或中央委託之機關提出展延申請，經核准展延之許可證有效期間為三年以上五年以下。第88條另定公告前設立之固定污染源應自公告之日起二年內申請操作許可證。",
 "How long are permits valid, when must renewal be filed, and how long is a renewal valid?",
 ["Valid five years; renewal must be filed three to six months before expiry; an approved renewal runs for three to five years","Valid three years; renewal must be filed one to three months before expiry; an approved renewal runs for five to ten years","Valid ten years; renewal must be filed six to twelve months before expiry; an approved renewal runs for one to three years","Valid five years; renewal may be filed within thirty days after expiry; an approved renewal always runs for a further five years"],
 "Article 30, paragraph 1."),

(AP,"第30條",3,"空污法-展延縮減",
 "許可證每次展延有效期間得縮減至未滿三年之情形，以及未於期限內申請展延之效果為何？",
 ["情形為違規情節重大經處分確定、設置操作未達五年、位於總量管制區；未於屆滿前申請展延者，許可證自屆滿日起失效","情形為曾申報不實、負責人變更、位於一級防制區；未於屆滿前申請展延者，許可證得自動延長一年後失效","情形為未設置專責人員、未依規定申報、位於二級防制區；未於屆滿前申請展延者，仍得繼續操作至完成審查為止","情形為排放量超過核定值、未繳空污費、位於空氣品質維護區；未於屆滿前申請展延者，主管機關應逕行換發新證"],"a",
 "第30條第1項但書：有下列情形之一者，每次展延有效期間得縮減至未滿三年：一、原許可證有效期間內違反本法規定情節重大經處分確定。二、固定污染源設置操作未達五年。三、固定污染源位於總量管制區。同條第2項：未於期限屆滿前申請展延者，於屆滿日起許可證失其效力，須繼續設置、操作或使用者應重新申請；因主管機關審查致無法完成准駁者，得依原許可證內容繼續操作。施行細則第19條定明設置操作未達五年之情形。",
 "When may a renewal be cut to under three years, and what if renewal is not filed in time?",
 ["Where a serious confirmed violation occurred, the source has operated under five years, or lies in a control zone; a late filing voids the permit at expiry","Where false reports were filed, the responsible person changed, or the source lies in a Class 1 district; a late filing extends the permit one year","Where no dedicated personnel were appointed, reports were missed, or the source lies in a Class 2 district; a late filing still allows operation","Where emissions exceeded approved values, fees went unpaid, or the source lies in a maintenance area; the authority then reissues the permit"],
 "Article 30, paragraphs 1 and 2; Enforcement Rules Article 19."),

(AP,"第31條",2,"空污法-國際公約物質",
 "對國際環保公約管制之易致空氣污染物質，中央主管機關有何權限？",
 ["得禁止或限制該物質及利用該物質製造或填充產品之製造、輸入、輸出、販賣或使用，並會商有關機關公告物質及產品","僅得對該物質之輸入及輸出加以限制，對其製造、販賣或使用則不得禁止，且無須公告受管制之物質清單","僅得要求業者申報使用量並繳納加倍之空氣污染防制費，不得禁止或限制其製造、輸入、輸出或販賣行為","應由經濟部公告受管制物質並禁止製造，中央主管機關僅得就使用行為訂定許可申請與審查程序之規定"],"a",
 "第31條：中央主管機關得禁止或限制國際環保公約管制之易致空氣污染物質及利用該物質製造或填充產品之製造、輸入、輸出、販賣或使用；物質及產品由中央主管機關會商有關機關公告，其許可申請、審查程序、廢止、記錄、申報等辦法亦由中央主管機關會商定之。違反輸入或輸出限制者依第52條處六月以上五年以下有期徒刑，違反許可、記錄、申報規定者依第68條處十萬元以上二百萬元以下罰鍰。",
 "What power does the central authority hold over substances controlled by treaties?",
 ["It may ban or restrict making, importing, exporting, selling or using such substances and products, announcing them with related agencies","It may restrict only import and export, may not ban manufacture, sale or use, and need not announce any list of controlled substances","It may only require reporting of use and a doubled pollution fee, and may not ban or restrict manufacture, import, export or sale","MOEA announces the controlled substances and bans manufacture, while the central authority sets only permit application procedures"],
 "Article 31; criminal penalty in Article 52, fines in Article 68."),

(AP,"第32條",2,"空污法-行為管制",
 "在各級防制區或總量管制區內，下列何者屬本法明文禁止之空氣污染行為？",
 ["從事營建工程、粉粒狀物堆置或運送工程材料而無適當防制措施，致引起塵土飛揚或污染空氣","於工廠內使用經核可之集塵設備從事研磨作業，且排放濃度符合中央主管機關所定排放標準","依主管機關核可之實施計畫從事消防演練，或取得山林田野引火燃燒許可而從事燃燒之行為","餐飲業依規定裝設油煙處理設施並維持正常運作，且未致散布油煙或異味污染物於周界外者"],"a",
 "第32條第1項第2款：在各級防制區或總量管制區內，不得從事營建工程、粉粒狀物堆置、運送工程材料、廢棄物或其他工事而無適當防制措施，致引起塵土飛揚或污染空氣；其餘各款包括產生明顯粒狀污染物、產生異味污染物或有毒氣體、使用有機溶劑致生異味、餐飲業烹飪散布油煙等。第90條則規定經核可之消防演練等行為免罰。違反者依第67條處罰。",
 "Which of the following is expressly prohibited as an air polluting act?",
 ["Carrying out construction, stockpiling granular material or hauling materials without proper control measures, causing dust or air pollution","Grinding in a plant using approved dust collection equipment where the discharge meets the emission standard set by the central authority","Conducting a fire drill under an implementation plan approved by the authority, or burning under a permit for open field burning","A restaurant that has installed and properly runs fume treatment equipment and does not spread cooking fumes or odours beyond its boundary"],
 "Article 32(1)(2); exemptions in Article 90; penalties in Article 67."),

(AP,"第32條",2,"空污法-行為管制範圍",
 "本法所稱空氣污染行為之範圍及其管制準則由何機關訂定？",
 ["空氣污染行為指未經排放管道排放之空氣污染行為；執行行為管制之準則由中央主管機關定之","空氣污染行為指經排放管道排放而超過排放標準之行為；管制準則由直轄市、縣（市）主管機關定之","空氣污染行為包括經排放管道與未經排放管道之所有排放行為；管制準則由目的事業主管機關定之","空氣污染行為指經檢舉並查證屬實之排放行為；管制準則由中央主管機關會商經濟部報行政院核定"],"a",
 "第32條第2項、第3項：第1項空氣污染行為，係指未經排放管道排放之空氣污染行為；第1項執行行為管制之準則，由中央主管機關定之（即空氣污染行為管制執行準則）。施行細則第22條並定明排放管道應符合設置採樣設施或依規定免設採樣設施之條件，未符合者視為未經排放管道排放。地方主管機關依第32條第1項第6款公告空氣污染行為者，應報請中央主管機關備查。",
 "What is the scope of an air polluting act and who sets the enforcement rules?",
 ["It means air pollution released other than through a stack; the enforcement rules are set by the central competent authority","It means release through a stack exceeding the emission standard; the enforcement rules are set by municipal or county authorities","It covers every release whether through a stack or not; the enforcement rules are set by the relevant industry competent authority","It means a release verified after a public complaint; the rules are set with MOEA and approved by the Executive Yuan"],
 "Article 32, paragraphs 2 and 3; Enforcement Rules Article 22."),

(AP,"第33條",3,"空污法-突發事故",
 "固定污染源因突發事故大量排放空氣污染物時，負責人應如何處理？",
 ["應立即採取緊急應變措施，並至遲於一小時內通報直轄市、縣（市）主管機關；並應擬訂緊急應變措施計畫報核定後執行","應於二十四小時內通報中央主管機關並提出書面報告，緊急應變措施計畫僅需自行留存備查無須報核定","應立即停止操作並於七日內通報直轄市、縣（市）主管機關，緊急應變措施計畫由主管機關代為擬訂","應於事故發生後十五日內通報目的事業主管機關，並由該機關發布空氣品質惡化警告及採取因應措施"],"a",
 "第33條：公私場所之固定污染源因突發事故大量排放空氣污染物時，負責人應立即採取緊急應變措施，並至遲於一小時內通報直轄市、縣（市）主管機關；主管機關除令採取必要措施或停止操作外，並應發布空氣品質惡化警告；公私場所應擬訂空氣污染突發事故緊急應變措施計畫，定期檢討，報經主管機關核定後切實執行。違反者依第59條處十萬元以上二千萬元以下罰鍰，致人於死者依第51條處無期徒刑或七年以上有期徒刑。",
 "What must the responsible person do when a sudden incident causes large emissions?",
 ["Take emergency response measures at once and notify the local competent authority within one hour; also file an approved response plan","Notify the central authority within twenty-four hours with a written report; the response plan is merely kept on file without approval","Halt operations at once and notify the local authority within seven days; the response plan is drawn up by the authority instead","Notify the relevant industry authority within fifteen days, and that authority issues the deterioration warning and response measures"],
 "Article 33; penalties in Articles 59 and 51."),

(AP,"第34條",2,"空污法-專責人員",
 "本法對公私場所設置專責單位或人員有何規定？",
 ["經中央指定公告之公私場所應設空氣污染防制專責單位或人員；經指定公告排放有害空氣污染物者並應設健康風險評估專責人員","所有公私場所均應設置空氣污染防制專責單位，健康風險評估則一律委託環境檢驗測定機構辦理即可","專責人員由直轄市、縣（市）主管機關派駐於公私場所，其薪資由公私場所負擔並報中央主管機關備查","專責人員資格由公私場所自行認定，僅需報請目的事業主管機關備查，無須經訓練或取得合格證書"],"a",
 "第34條：經中央主管機關指定公告之公私場所應設置空氣污染防制專責單位或人員；經中央主管機關指定公告排放有害空氣污染物之公私場所應設置健康風險評估專責人員；專責人員應符合中央主管機關規定之資格，並經訓練取得合格證書。違反者依第69條第1項第1款處二十萬元以上二百萬元以下罰鍰，專責人員違反訓練及執行業務規定者依同條第2項處一萬元以上十萬元以下罰鍰。",
 "What does the Act require on dedicated units and personnel?",
 ["Designated premises must set up an air pollution control unit or personnel; those emitting hazardous pollutants must add health risk assessment staff","Every premises must set up a control unit, while health risk assessment may simply be commissioned to a licensed testing organization","Dedicated personnel are seconded by the local authority to the premises, which pay their salaries and file the arrangement centrally","Premises decide the qualifications of their own personnel and merely notify the industry authority, with no training or certificate needed"],
 "Article 34; penalties in Article 69."),

(AP,"第35條",2,"空污法-資訊公開",
 "公私場所依本法應將哪些資料公開於中央主管機關指定之網站？",
 ["設置與操作許可證及所含防制計畫、燃料使用許可證、依法申報資料、技師與專責人員證號及突發事故緊急應變措施計畫","僅需公開空氣污染防制費繳費證明及年度排放量統計，其餘許可證及申報資料均屬工商機密不得公開","僅需公開由主管機關查核及處分之統計資訊，個別公私場所之許可證及申報資料一律不予公開","應公開全部原料配方、產品產量及財務報表，但許可證及專責人員證號資料則不在公開範圍內"],"a",
 "第35條：公私場所應將主管機關核發之固定污染源設置與操作許可證（應含空氣污染防制計畫及防制設施說明書）、燃料使用許可證及依本法申報之資料，與環境工程技師、空氣污染防制專責人員及環境檢驗測定機構之證號資料，以及突發事故緊急應變措施計畫，公開於中央主管機關指定之網站；涉及國防機密或經核准之工商機密者除外。違反者依第69條第1項第2款處罰。",
 "Which materials must premises publish on the website designated centrally?",
 ["Installation and operating permits with the control plan, fuel use permit, filed reports, engineer and personnel licence numbers, and the response plan","Only proof of air pollution fee payment and the annual emission statistics, since the permits and filed reports are trade secrets not to be disclosed","Only the statistics on audits and penalties issued by the authority, while individual permits and filed reports are never disclosed","All raw material formulas, product output and financial statements, but not permits or the licence numbers of dedicated personnel"],
 "Article 35; penalties in Article 69(1)(2)."),

(AP,"第36條",3,"空污法-移動源標準",
 "關於移動污染源排放標準及減效裝置，本法有何規定？",
 ["移動污染源應符合排放標準，中央得加嚴出廠十年以上交通工具原適用標準；製造者或進口商禁止安裝影響排放之減效裝置","移動污染源僅需符合出廠時之排放標準，中央不得加嚴；減效裝置經目的事業主管機關同意後即得安裝使用","移動污染源之排放標準由地方主管機關訂定，中央得加嚴出廠五年以上車輛之標準；減效裝置一律禁止安裝","使用中汽車得抽驗合格即可免逐車檢驗；減效裝置僅禁止使用人安裝，製造者及進口商則不受此限制"],"a",
 "第36條：移動污染源排放空氣污染物應符合排放標準，該標準由中央主管機關會商有關機關定之，並得視空氣品質需求加嚴出廠十年以上交通工具原適用之排放標準；使用中汽車無論國產或進口均需逐車完成檢驗並符合排放標準；汽車之製造者或進口商禁止安裝任何影響交通工具排放空氣污染物之減效裝置，但具備保護或防止損壞避免意外事故必備功能、或使引擎起動及暖車後不再作動之機制者除外。違反第5項者依第66條第2項按每輛處十萬元以上五百萬元以下罰鍰。",
 "What does the Act provide on mobile source standards and defeat devices?",
 ["Mobile sources must meet standards, which may be tightened for vehicles over ten years old; makers and importers may not fit defeat devices","Mobile sources need only meet the standard at manufacture and it may not be tightened; defeat devices may be fitted with industry consent","Local authorities set mobile source standards and the centre may tighten them for vehicles over five years old; defeat devices are all banned","Sample testing of in-use cars suffices instead of per-vehicle testing; only users are barred from fitting defeat devices, not makers"],
 "Article 36; penalties in Article 66(2)."),

(AP,"第37條",2,"空污法-防制設備",
 "移動污染源使用人或所有人對其空氣污染防制設備有何義務？",
 ["應維持防制設備之有效運作，並不得拆除或改裝非經中央主管機關認證之空氣污染防制設備","得於車輛檢驗合格後拆除防制設備，惟應於三十日內向直轄市、縣（市）主管機關報備","僅須於定期檢驗時裝回原廠防制設備即可，平時得改裝為非經認證之設備而不受限制","應每年委託檢驗測定機構檢測防制設備效能一次，設備種類及規格則由使用人自行決定"],"a",
 "第37條：移動污染源使用人或所有人應維持其空氣污染防制設備之有效運作，並不得拆除或不得改裝非經中央主管機關認證之空氣污染防制設備；設備種類、規格、效能確認方式、標識、認證等辦法由中央主管機關定之。違反者依第66條第1項第2款處一千五百元以上六萬元以下罰鍰，並通知限期改善，屆期未改善者按次處罰。",
 "What duty does a mobile source user or owner have regarding control equipment?",
 ["Keep the control equipment operating effectively and neither remove it nor refit equipment not certified by the central authority","May remove the control equipment once the vehicle passes inspection, provided the local authority is notified within thirty days","Need only refit the original equipment at periodic inspection and may otherwise use uncertified equipment without restriction","Must have the equipment's performance tested yearly by a testing organization, while choosing its type and specification freely"],
 "Article 37; penalties in Article 66(1)(2)."),

(AP,"第38條",1,"空污法-怠速",
 "汽車於一定場所、地點、氣候條件以怠速停車時，本法如何管制？",
 ["其怠速時間應符合中央主管機關之規定，車種、場所、地點、氣候條件與停車怠速時間之辦法由中央主管機關定之","其怠速時間一律不得超過十分鐘，並由目的事業主管機關依車種訂定不同之怠速停車時間上限","其怠速停車行為一律禁止，違反者處新臺幣一萬元以上十萬元以下罰鍰，並吊扣其汽車牌照","其怠速時間由直轄市、縣（市）主管機關逐案核定，中央主管機關僅得訂定檢舉獎勵之辦法"],"a",
 "第38條：汽車於一定場所、地點、氣候條件以怠速停車時，其怠速時間應符合中央主管機關之規定；汽車之種類、一定場所、地點、氣候條件與停車怠速時間及其他應遵行事項之辦法，由中央主管機關定之。違反該辦法有關怠速停車限制之規定者，依第76條第1項處汽車使用人或所有人一千五百元以上六萬元以下罰鍰，並得令其改善，未改善者按次處罰至改善為止。",
 "How does the Act regulate idling while parked at certain places and conditions?",
 ["Idling time must comply with central rules, and regulations cover vehicle types, places, locations, weather conditions and idling time","Idling may never exceed ten minutes, with industry authorities setting different idling limits according to the type of vehicle","Idling while parked is banned outright, punishable by a fine of NT$10,000 to NT$100,000 and suspension of the licence plate","Idling time is approved case by case by local authorities, while the central authority may only set whistleblower reward rules"],
 "Article 38; penalties in Article 76(1)."),

(AP,"第39條",3,"空污法-燃料管理",
 "製造、進口移動污染源用燃料者，依本法應遵守哪些規定？",
 ["應符合中央所定燃料種類及成分標準；製造者應取得許可始得於國內販賣，進口者應取得許可文件；並應逐批（船）次檢驗分析並申報","應符合直轄市、縣（市）主管機關所定成分標準；製造者免取得許可即得販賣，進口者僅需向海關報關後即可輸入使用","應符合中央所定成分標準；製造與進口者均免取得許可，但應每年抽驗一次並將結果留存五年備查","應由目的事業主管機關核定成分規格；專供出口之燃料亦應符合國內標準，且無須進行成分檢驗分析"],"a",
 "第39條：製造、進口、販賣或使用供移動污染源用之燃料，應符合中央主管機關所定燃料種類及成分之標準，但專供出口者不在此限；燃料製造者應取得中央主管機關核發之許可，其生產之燃料始得於國內販賣，進口者應取得許可文件始得申請輸入同意文件；製造或進口者應對每批（船）次燃料進行成分之檢驗分析，並作成紀錄向中央主管機關申報。違反者依第73條處十萬元以上一百萬元以下罰鍰，使用人違反者處五千元以上十萬元以下罰鍰。",
 "What must makers and importers of mobile source fuels comply with?",
 ["Meet central fuel type and composition standards; makers need a licence to sell domestically and importers a permit; each batch must be tested and reported","Meet composition standards set locally; makers may sell without a licence and importers may bring fuel in once customs clearance is completed","Meet central composition standards; neither makers nor importers need a licence, but one sample a year is tested and kept on file for five years","Have specifications approved by the industry authority; export-only fuel must also meet domestic standards and no composition testing is needed"],
 "Article 39; penalties in Article 73."),

(AP,"第40條",2,"空污法-空品維護區",
 "各級主管機關劃設空氣品質維護區後，得採行哪些移動污染源管制措施？程序為何？",
 ["得禁止或限制特定汽車進入、限制所使用燃料動力型式操作條件運行狀況及進入等措施；管制措施由地方擬訂報中央核定後公告","僅得禁止大型柴油車輛及機車進入，不得限制燃料種類或動力型式；管制措施由地方主管機關逕行公告實施","得對區內固定污染源加嚴排放標準並命其停工；管制措施由中央主管機關訂定後交由地方執行公告","得禁止所有車輛進入並收取空氣品質維護費；管制措施由目的事業主管機關擬訂報行政院核定公告"],"a",
 "第40條：各級主管機關得視空氣品質需求及污染特性，因地制宜劃設空氣品質維護區，實施移動污染源管制措施；管制得包括禁止或限制特定汽車進入、禁止或限制移動污染源所使用之燃料、動力型式、操作條件、運行狀況及進入，及其他可改善空氣品質之管制措施；管制措施由直轄市、縣（市）主管機關擬訂，報中央主管機關核定後公告之。違反公告之管制措施者依第76條第2項處罰。",
 "What mobile source controls may apply in an air quality maintenance area, and how are they adopted?",
 ["Banning or limiting entry of certain vehicles and limiting fuel, power type, operating conditions, running state and entry; localities draft, the centre approves","Only large diesel vehicles may be barred and fuel or power type may not be limited; local authorities announce the measures on their own","Stricter emission standards and shutdown orders may be imposed on stationary sources in the area; the centre sets the measures for the localities to announce","All vehicles may be barred and a maintenance fee charged; industry authorities draft the measures for Executive Yuan approval"],
 "Article 40; penalties in Article 76(2)."),

(AP,"第41條",2,"空污法-召回改正",
 "中央主管機關抽驗使用中汽車，研判因設計或裝置不良致無法符合排放標準時，應如何處理？",
 ["應責令製造者或進口商將已出售之汽車限期召回改正；屆期仍不遵行者，應停止其製造、進口及銷售","應命汽車所有人自費修復並於一個月內複驗，製造者或進口商僅需分攤半數修復費用即可免責","應逕予註銷該車型之排氣審驗合格證明，並命所有人於六個月內報廢該車輛，不得要求召回","應移送司法機關偵辦，並由目的事業主管機關命製造者或進口商暫停生產至改正完成為止"],"a",
 "第41條：中央主管機關抽驗使用中汽車空氣污染物排放情形，經研判其無法符合移動污染源空氣污染物排放標準，因設計或裝置不良所致者，應責令製造者或進口商將已出售之汽車限期召回改正；屆期仍不遵行者，應停止其製造、進口及銷售。不遵行召回改正命令者依第77條第1項按每輛汽車處新臺幣十萬元罰鍰。",
 "What happens when sampled in-use cars fail standards due to poor design or fitting?",
 ["The maker or importer must recall and correct sold vehicles within a set period; if it still fails to comply, making, import and sale must stop","The owner must repair at own cost and retest within a month, and the maker or importer escapes liability by paying half the repair cost","The type approval certificate is revoked and owners must scrap the vehicles within six months, with no recall being ordered at all","The case goes to prosecutors and the industry authority suspends production until the correction has been completely carried out"],
 "Article 41; penalties in Article 77(1)."),

(AP,"第42條",2,"空污法-車型審驗",
 "汽車申請牌照前，依本法應完成何種程序？",
 ["應取得中央主管機關核發之車型排氣審驗合格證明，並經中央主管機關驗證核章後，始得申請牌照","應取得公路監理機關核發之排氣檢驗合格證明，並由製造者自行核章後，即得逕行申請牌照","應取得環境檢驗測定機構出具之排放檢測報告，報請直轄市、縣（市）主管機關備查後申請牌照","應取得目的事業主管機關核發之能效標章，並由中央主管機關抽驗合格後，始得申請領用牌照"],"a",
 "第42條：汽車應取得中央主管機關核發之車型排氣審驗合格證明，並經中央主管機關驗證核章，始得申請牌照；審驗合格證明之核發、撤銷、廢止等辦法及驗證核章之辦法，由中央主管機關（會商有關機關）定之。違反核發及管理事項規定者依第78條第1款處五千元以上二十萬元以下罰鍰。第36條第5項違規者並得撤銷其車型排氣審驗合格證明。",
 "What must be completed before applying for a vehicle licence plate?",
 ["Obtain the vehicle type emission approval certificate issued centrally and have it verified and stamped by the central authority","Obtain an emission test certificate from the motor vehicle office and have the maker stamp it, then apply for the plate directly","Obtain an emission test report from a licensed testing organization and file it with the local authority before applying for the plate","Obtain an energy efficiency label from the industry authority and pass central sample testing before applying for the licence plate"],
 "Article 42; penalties in Article 78(1)."),

(AP,"第43條",2,"空污法-委託檢驗",
 "關於汽車排氣定期檢驗之委託，本法有何規定？",
 ["中央主管機關得委託其他機關辦理汽車排氣定期檢驗並支付委託費用，其費用得由汽車排氣檢驗費扣抵","中央主管機關應自行辦理汽車排氣定期檢驗，不得委託其他機關，檢驗費用一律由公務預算支應","地方主管機關得委託民間檢驗機構辦理定期檢驗，費用由車主全額負擔，不得自檢驗費中扣抵","目的事業主管機關得委託公路監理機關辦理定期檢驗，其委託費用應由中央主管機關逐年編列補助"],"a",
 "第43條：中央主管機關得委託其他機關辦理汽車排氣定期檢驗，並支付委託費用，其費用得由汽車排氣檢驗費扣抵；交通工具排放空氣污染物檢驗、處理、委託及其他應遵行事項之辦法，由中央主管機關會商中央交通主管機關定之。違反該辦法有關檢驗、處理管理事項之規定者，依第78條第2款處五千元以上二十萬元以下罰鍰。",
 "What does the Act say about commissioning periodic vehicle emission inspections?",
 ["The central authority may commission other agencies and pay the fee, which may be offset against the vehicle emission inspection charge","The central authority must run periodic inspections itself and may not commission others, with all costs met from the public budget","Local authorities may commission private inspection bodies, with owners bearing the full cost and no offset against the charge","Industry authorities may commission the motor vehicle office, with the commission fee subsidized annually by the central authority"],
 "Article 43; penalties in Article 78(2)."),

(AP,"第44條",2,"空污法-定期檢驗",
 "汽車排放空氣污染物定期檢驗不符合排放標準者，應如何處理？",
 ["應於檢驗日起一個月內修復並申請複驗；檢驗實施之對象、區域、頻率及期限由中央主管機關公告之","應於檢驗日起三個月內修復並申請複驗；檢驗實施之對象、區域及頻率由直轄市、縣（市）主管機關公告","應於檢驗日起七日內辦理報廢或過戶；檢驗實施之對象及頻率由公路監理機關會商中央主管機關公告","應於檢驗日起一年內修復並申請複驗；期間得繼續使用，檢驗頻率由汽車製造者依車型自行訂定"],"a",
 "第44條：汽車應實施排放空氣污染物定期檢驗，檢驗不符合第36條第2項所定排放標準之車輛，應於檢驗日起一個月內修復，並申請複驗；檢驗實施之對象、區域、頻率及期限由中央主管機關公告之；檢驗站設置之條件、設施、檢驗人員資格等辦法由中央主管機關定之。未實施定期檢驗者依第80條第1項處五百元以上一萬五千元以下罰鍰。",
 "What must be done when a vehicle fails its periodic emission inspection?",
 ["Repair it within one month of the inspection date and apply for retest; the centre announces the targets, areas, frequency and deadlines","Repair it within three months of the inspection date and apply for retest; local authorities announce targets, areas and frequency","Scrap or transfer the vehicle within seven days; the motor vehicle office announces targets and frequency with the central authority","Repair within one year of inspection and apply for retest, using the vehicle meanwhile; makers set frequency by vehicle model"],
 "Article 44; penalties in Article 80."),

(AP,"第45條",2,"空污法-不定期檢驗",
 "各級主管機關得於何處實施使用中移動污染源之不定期檢驗或檢查？",
 ["得於車（場）站、機場、道路、港區、水域或其他適當地點實施，或通知有污染之虞交通工具於指定期限至指定地點受檢","僅得於公路監理站及指定之檢驗站內實施，不得於道路、港區或水域對移動污染源實施不定期檢驗","僅得於經行政院核定之空氣品質維護區內實施，且不得通知車輛至指定地點接受檢驗或檢查","得於任何地點實施，但僅限於接獲民眾檢舉之車輛，主動抽檢須報請中央主管機關逐案核准"],"a",
 "第45條：各級主管機關得於車（場）站、機場、道路、港區、水域或其他適當地點實施使用中移動污染源排放空氣污染物不定期檢驗或檢查，或通知有污染之虞交通工具於指定期限至指定地點接受檢驗；其辦法由中央主管機關會商有關機關定之。不依規定檢驗或檢驗不符合排放標準者，依第79條處一千五百元以上六萬元以下罰鍰，並通知限期改善。",
 "Where may authorities carry out unscheduled inspections of in-use mobile sources?",
 ["At terminals, airports, roads, port areas, waters or other suitable places, or by summoning suspect vehicles to a designated place by a deadline","Only inside motor vehicle offices and designated inspection stations, and never on roads, in port areas or on any waters for mobile sources","Only within air quality maintenance areas approved by the Executive Yuan, and vehicles may not be summoned to a designated place","Anywhere, but only for vehicles reported by the public, since proactive sampling needs case-by-case central approval first"],
 "Article 45; penalties in Article 79."),

(AP,"第46條",2,"空污法-目測遙測",
 "使用中汽車經檢查人員目測、目視或遙測不符合排放標準或遙測篩選標準者，應如何處理？",
 ["應於直轄市、縣（市）主管機關通知之期限內修復，並至指定地點接受檢驗；被檢舉之車輛經通知者亦同","應於通知後三日內辦理報廢，不得申請修復及複驗；被檢舉之車輛則僅需書面說明即可免除受檢","應由主管機關逕行處以罰鍰並吊扣牌照，車主不得申請修復；人民不得對使用中汽車提出檢舉","應由汽車製造者負責限期召回改正，車主無須將車輛送至指定地點接受檢驗或辦理任何修復"],"a",
 "第46條：使用中之汽車排放空氣污染物，經直轄市、縣（市）主管機關檢查人員目測、目視或遙測不符合第36條第2項所定排放標準或中央主管機關公告之遙測篩選標準者，應於主管機關通知之期限內修復，並至指定地點接受檢驗；人民得向各級主管機關檢舉使用中汽車排放情形，被檢舉之車輛經通知者，應於指定期限內至指定地點接受檢驗。違反者依第79條處罰。",
 "What follows when an in-use car fails visual or remote sensing screening?",
 ["It must be repaired within the period notified by the local authority and taken to a designated place for testing; notified reported cars likewise","It must be scrapped within three days of notice with no repair or retest allowed; a reported car escapes testing by a written explanation","The authority fines the owner and suspends the plate with no repair option, and the public may not report in-use vehicles at all","The maker must recall and correct it within a set period, and the owner need not present the car for testing or arrange repairs"],
 "Article 46; penalties in Article 79."),

(AP,"第47條",2,"空污法-VOC製品",
 "製造、進口、販賣含揮發性有機物之化學製品，本法有何規定？",
 ["經中央主管機關指定公告者，應符合該化學製品之含揮發性有機物成分標準，但專供出口者不在此限","所有化學製品均應符合含揮發性有機物成分標準，專供出口者亦不得例外，違者一律移送司法機關","僅製造者須符合成分標準，進口及販賣者不受限制，且成分標準由目的事業主管機關按產業別訂定","應逐批申請中央主管機關核發之使用許可證，成分標準則由直轄市、縣（市）主管機關公告實施"],"a",
 "第47條：製造、進口、販賣經中央主管機關指定公告含揮發性有機物之化學製品，應符合該化學製品之含揮發性有機物成分標準，但專供出口者不在此限；成分標準由中央主管機關會商有關機關定之。違反者依第72條處製造、進口或販賣者十萬元以上一百萬元以下罰鍰，並通知限期改善，屆期未完成改善者按次處罰。第3條第14款並定義含揮發性有機物化學製品。",
 "What applies to chemical products containing volatile organic compounds?",
 ["Those designated by the central authority must meet the VOC content standard for that product, except products made solely for export","All chemical products must meet the VOC content standard with no export exception, and violators are referred for prosecution","Only makers must meet the standard while importers and sellers are free, and industry authorities set standards by sector","A use permit must be obtained batch by batch from the centre, while local authorities announce the content standards"],
 "Article 47; penalties in Article 72."),

(AP,"第48條",2,"空污法-檢查權",
 "各級主管機關依本法行使檢查權，相關規定為何？",
 ["得派員攜帶證明文件檢查或鑑定排放狀況、防制設施及燃料成分並令提供資料；受檢者不得規避、妨礙或拒絕","得逕行進入公私場所檢查而免出示證明文件；受檢者得以涉及工商機密為由拒絕提供任何相關資料","僅得於接獲檢舉時派員檢查，且不得要求提供資料；涉及軍事機密者應報請行政院核准後始得檢查","僅得檢查固定污染源，移動污染源之檢查應由公路監理機關為之；受檢者得拒絕鑑定但不得拒絕檢查"],"a",
 "第48條：各級主管機關得派員攜帶證明文件，檢查或鑑定公私場所或移動污染源空氣污染物排放狀況、收集設施、防制設施、監測設施或燃料成分、含揮發性有機物化學製品成分，並令提供有關資料；涉及軍事機密者應會同軍事機關為之；對於檢查、鑑定及命令不得規避、妨礙或拒絕；公私場所應具備便於實施檢查及鑑定之設施。違反者依第71條處公私場所二十萬元以上一百萬元以下罰鍰。",
 "What are the rules on inspection powers under the Act?",
 ["Officials with credentials may inspect emissions, control facilities and fuel composition and demand data; evasion or refusal is prohibited","Officials may enter premises without showing credentials, and those inspected may refuse all data on grounds of trade secrecy","Inspections occur only upon complaint and no data may be demanded; military secrets require Executive Yuan approval first","Only stationary sources may be inspected, mobile ones by the motor vehicle office; refusal of appraisal is allowed but not of inspection"],
 "Article 48; penalties in Article 71."),

(AP,"第49條",2,"空污法-檢測機構",
 "環境檢驗測定機構辦理本法規定之檢驗測定，應具備何種資格？",
 ["應取得中央主管機關核給之許可證後始得辦理；其應具備條件、設施、人員資格、查核及評鑑程序等辦法由中央主管機關定之","應向直轄市、縣（市）主管機關辦理登記後即得辦理；人員資格及設施條件由機構依業務需要自行訂定","應取得目的事業主管機關核發之營業執照即可辦理，檢驗測定方法則由各機構參考國際規範自訂","應由中央主管機關委託之學術機構認證後辦理，並免受主管機關之查核、評鑑及停業處分之規範"],"a",
 "第49條：檢驗測定機構應取得中央主管機關核給之許可證後，始得辦理本法規定之檢驗測定；其應具備之條件、設施、檢驗測定人員資格限制、許可之申請、審查程序、撤銷、廢止、許可證核（換）發、停業、復業、查核、評鑑程序等辦法由中央主管機關定之；本法各項檢驗測定方法由中央主管機關定之。違反者依第70條處二十萬元以上一百萬元以下罰鍰。",
 "What qualification must an environmental testing organization hold?",
 ["It must obtain a licence issued by the central authority; conditions, facilities, personnel, audit and appraisal rules are set centrally","It may act after registering with the local competent authority, setting its own personnel qualifications and facility conditions","A business licence from the industry authority suffices, and each body may devise its own testing methods from international norms","Accreditation by an academic body commissioned centrally suffices, and it is exempt from audits, appraisals and suspension rules"],
 "Article 49; penalties in Article 70."),

(AP,"第50條",1,"空污法-輔導",
 "各種污染源之改善，依本法由何機關輔導？其輔導成果應如何處理？",
 ["由各目的事業主管機關輔導；相關輔導成果應每年公開於中央主管機關指定之網站，並定期檢討之","由中央主管機關統一輔導；輔導成果每三年檢討一次，並僅送立法院備查而不對外公開揭露","由直轄市、縣（市）主管機關輔導；輔導成果應報請行政院核定後，公開於地方主管機關網站","由環境檢驗測定機構受託輔導；輔導成果僅供主管機關內部參考，不予公開亦無須定期檢討"],"a",
 "第50條：各種污染源之改善，由各目的事業主管機關輔導之，相關輔導成果應每年公開於中央主管機關指定之網站，並定期檢討之。第4條另規定各級主管機關得指定或委託（任）專責機關（構）辦理空氣污染訓練及防制之有關事宜。",
 "Who guides the improvement of pollution sources and how are results handled?",
 ["The relevant industry competent authorities guide it; results are published yearly on the centrally designated website and reviewed regularly","The central authority alone guides it; results are reviewed every three years and merely filed with the Legislative Yuan, not published","Municipal and county authorities guide it; results go to the Executive Yuan for approval and appear on the local authority website","Licensed testing organizations are commissioned to guide it; results are internal only, never published and never periodically reviewed"],
 "Article 50."),
]
